import datetime
import json
import os
from pathlib import Path
import signal
import sys
import time
import traceback
import uuid

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import observe

ACCOUNT = '000000000000'
REGION = 'us-east-1'
PREFIX = 'stackd-sns-archive-deny-' + uuid.uuid4().hex[:10]
OUTPUT = ROOT / 'testdata/aws/sns/archive_kms_deny.json'
ENV = {k: v for k, v in os.environ.items() if not k.startswith('AWS_ENDPOINT_URL')}
ENV.update(AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_PAGER='')
T0 = time.monotonic()
STOP = False
CASES = []
QUEUES = []
SUBS = []

def stamp():
    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00', 'Z')

DATA = {'account': ACCOUNT, 'region': REGION, 'prefix': PREFIX, 'started': stamp(), 'observations': [], 'receipts': [], 'windows': [], 'cleanup': [], 'cases': CASES,
        'sources': ['https://docs.aws.amazon.com/sns/latest/dg/message-archiving-and-replay-topic-owner.html#message-archiving-and-replay-topic-kms', 'https://docs.aws.amazon.com/kms/latest/developerguide/logging-using-cloudtrail.html'],
        'experiment_design': 'Two same-age isolated encrypted FIFO archives, initially identical documented grants and actual baseline replays. Add only explicit sns.amazonaws.com kms:Decrypt Deny to the treatment key, preserving owner/publisher rights. Both original keys stay Enabled until final cleanup. Fresh standard SQS queues and subscriptions avoid consumer deduplication. After twenty minutes, request both original replays and capture actual receipts/status. Remove only the treatment service Deny, request fresh original recovery, and correlate EventName=Decrypt CloudTrail events using exact owned resources. Elapsed time never establishes a cache miss.',
        'limitations': ['Bounded receive absence is not a native Failed status or universal timeout.', 'Fresh queues do not guarantee a fresh SNS archive cache.', 'CloudTrail event history is eventually consistent and missing failed calls cannot prove they did not occur.', 'An allowed independent same-age archive is a scheduling control, not proof of the treatment cache state.', 'Only owned topics, subscriptions, queues and two tagged customer-managed keys are created; keys remain PendingDeletion for seven days.'],
        'redaction_note': 'CloudTrail events retain all native fields except accessKeyId, secretAccessKey, sessionToken and confirmationToken values are replaced with [REDACTED]. Unrelated account events are omitted with counts; matching CloudTrailEvent JSON is reserialized. No new credentials are created.'}

def save():
    DATA['updated'] = stamp()
    OUTPUT.write_text(json.dumps(DATA, indent=2) + '\n')

def redact(value):
    if isinstance(value, dict):
        return {k: ('[REDACTED]' if k.lower() in ('accesskeyid', 'secretaccesskey', 'sessiontoken', 'confirmationtoken') else redact(v)) for k,v in value.items()}
    if isinstance(value, list):
        return [redact(v) for v in value]
    return value

def call(label, service, operation, parameters=None, strict=True, cleanup=False, paginate=False):
    begun = stamp()
    result = observe(service, operation, parameters or {}, ENV, paginate=paginate)
    selection = None
    if service == 'cloudtrail' and result['code'] == 'Success':
        events = result.get('output', {}).get('Events', [])
        kept = []
        keys = {c.get('key_arn') for c in CASES} | {c.get('key') for c in CASES}
        topics = {c.get('topic') for c in CASES}
        for event in events:
            native = json.loads(event['CloudTrailEvent'])
            request = native.get('requestParameters') or {}
            resources = {r.get('ARN') for r in native.get('resources', [])}
            context = request.get('encryptionContext') or {}
            if request.get('keyId') in keys or bool(resources & keys) or context.get('aws:sns:topicArn') in topics:
                event = redact(event)
                event['CloudTrailEvent'] = json.dumps(redact(native))
                kept.append(event)
        selection = {'selector': 'EventName=Decrypt; exact owned key id/ARN or exact owned topic encryption context', 'returned_event_count': len(events), 'retained_owned_event_count': len(kept), 'omitted_unrelated_event_count': len(events)-len(kept)}
        result['output']['Events'] = kept
    row = {'label': label, 'service': service, 'operation': operation, 'input': parameters or {}, 'result': result, 'started': begun, 'observed': stamp()}
    if selection:
        row['event_selection'] = selection
    DATA['cleanup' if cleanup else 'observations'].append(row)
    save()
    if strict and result['code'] != 'Success':
        raise RuntimeError(label + ': ' + json.dumps(result))
    return result.get('output', {})

def stop(signum, frame):
    global STOP
    STOP = True
signal.signal(signal.SIGINT, stop)
signal.signal(signal.SIGTERM, stop)

def check():
    if STOP or time.monotonic() - T0 > 2100:
        raise RuntimeError('Experiment stop/deadline; reserving cleanup time')

def until(seconds, label):
    start = stamp()
    while time.monotonic() - T0 < seconds:
        check()
        time.sleep(1)
    DATA['windows'].append({'label': label, 'start': start, 'end': stamp(), 'kind': 'idle; not evidence of cold cache'})
    save()

def policy(denied):
    rows = [{'Sid': 'OwnerPublisherUnchanged', 'Effect': 'Allow', 'Principal': {'AWS': f'arn:aws:iam::{ACCOUNT}:root'}, 'Action': 'kms:*', 'Resource': '*'},
            {'Sid': 'DocumentedSNSArchiveGrant', 'Effect': 'Allow', 'Principal': {'Service': 'sns.amazonaws.com'}, 'Action': ['kms:Decrypt','kms:GenerateDataKey'], 'Resource': '*'}]
    if denied:
        rows.append({'Sid': 'ExplicitSNSDecryptDeny', 'Effect': 'Deny', 'Principal': {'Service': 'sns.amazonaws.com'}, 'Action': 'kms:Decrypt', 'Resource': '*'})
    return json.dumps({'Version':'2012-10-17','Statement':rows})

def create_case(name):
    c = {'name': name}
    CASES.append(c)
    c['topic'] = call(name+'-create-topic','sns','create-topic',{'Name':PREFIX+'-'+name+'.fifo','Attributes':{'FifoTopic':'true','ArchivePolicy':'{"MessageRetentionPeriod":1}'},'Tags':[{'Key':'stackd-probe','Value':PREFIX}]})['TopicArn']
    key = call(name+'-create-key','kms','create-key',{'Description':PREFIX+'-'+name,'Policy':policy(False),'Tags':[{'TagKey':'stackd-probe','TagValue':PREFIX}]})['KeyMetadata']
    c['key'] = key['KeyId']
    c['key_arn'] = key['Arn']
    save()
    call(name+'-configure-encryption','sns','set-topic-attributes',{'TopicArn':c['topic'],'AttributeName':'KmsMasterKeyId','AttributeValue':c['key']})
    c['archive_start'] = call(name+'-archive-attributes','sns','get-topic-attributes',{'TopicArn':c['topic']})['Attributes']['BeginningArchiveTime']
    return c

def destination(c, label, replay):
    label=c['name']+'-'+label
    q=call(label+'-queue','sqs','create-queue',{'QueueName':PREFIX+'-'+label,'tags':{'stackd-probe':PREFIX}})['QueueUrl']
    QUEUES.append(q)
    save()
    arn=call(label+'-queue-arn','sqs','get-queue-attributes',{'QueueUrl':q,'AttributeNames':['QueueArn']})['Attributes']['QueueArn']
    p={'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'sns.amazonaws.com'},'Action':'sqs:SendMessage','Resource':arn,'Condition':{'ArnEquals':{'aws:SourceArn':c['topic']}}}]}
    call(label+'-queue-policy','sqs','set-queue-attributes',{'QueueUrl':q,'Attributes':{'Policy':json.dumps(p)}})
    inp={'TopicArn':c['topic'],'Protocol':'sqs','Endpoint':arn,'ReturnSubscriptionArn':True}
    if replay:
        inp['Attributes']={'ReplayPolicy':json.dumps({'PointType':'Timestamp','StartingPoint':c['archive_start']})}
    sub=call(label+'-subscribe','sns','subscribe',inp)['SubscriptionArn']
    SUBS.append(sub)
    save()
    call(label+'-initial-status','sns','get-subscription-attributes',{'SubscriptionArn':sub})
    return q,sub

def receive(c,label,q,sub,seconds=90):
    start=stamp()
    until_time=time.monotonic()+seconds
    matched=False
    while time.monotonic()<until_time:
        check()
        out=call(c['name']+'-'+label+'-receive','sqs','receive-message',{'QueueUrl':q,'WaitTimeSeconds':min(20,max(1,int(until_time-time.monotonic()))),'MaxNumberOfMessages':10,'MessageSystemAttributeNames':['All'],'MessageAttributeNames':['All']})
        for msg in out.get('Messages',[]):
            retained={k:v for k,v in msg.items() if k!='ReceiptHandle'}
            body=json.loads(msg['Body'])
            is_match=body.get('MessageId')==c['publication']['MessageId'] and body.get('Message')==c['message'] and body.get('TopicArn')==c['topic']
            DATA['receipts'].append({'label':c['name']+'-'+label,'observed':stamp(),'queue':q,'subscription':sub,'matches_original_publication':is_match,'message':retained})
            matched = matched or is_match
            call(c['name']+'-'+label+'-delete-receipt','sqs','delete-message',{'QueueUrl':q,'ReceiptHandle':msg['ReceiptHandle']})
        if matched:
            break
    attrs=call(c['name']+'-'+label+'-status','sns','get-subscription-attributes',{'SubscriptionArn':sub}).get('Attributes',{})
    DATA['windows'].append({'label':c['name']+'-'+label,'start':start,'end':stamp(),'requested_max_receive_seconds':seconds,'receipt_observed':matched,'ReplayStatus':attrs.get('ReplayStatus')})
    save()
    return matched

def replay(c,label):
    q,sub=destination(c,label,True)
    return receive(c,label,q,sub)

def controls(c,label):
    metadata=call(c['name']+'-'+label+'-enabled-key','kms','describe-key',{'KeyId':c['key']})['KeyMetadata']
    if metadata['KeyState']!='Enabled' or not metadata['Enabled']:
        raise RuntimeError('Key unexpectedly not Enabled')
    call(c['name']+'-'+label+'-policy','kms','get-key-policy',{'KeyId':c['key'],'PolicyName':'default'})

def trail(label):
    return call(label,'cloudtrail','lookup-events',{'LookupAttributes':[{'AttributeKey':'EventName','AttributeValue':'Decrypt'}],'StartTime':DATA['started'],'EndTime':stamp()},strict=False,paginate=True)

def cleanup_call(*args,**kwargs):
    try:
        return call(*args,**kwargs,strict=False,cleanup=True)
    except Exception as exc:
        DATA.setdefault('cleanup_transport_errors',[]).append({'label':args[0],'error':str(exc),'observed':stamp()})
        save()
        return {}

try:
    identity=call('identity','sts','get-caller-identity')
    if identity.get('Account')!=ACCOUNT or identity.get('Arn')!=f'arn:aws:iam::{ACCOUNT}:user/Delegated':
        raise RuntimeError('Unexpected identity; refusing resource creation')
    print('ArchiveDeny identity confirmed',flush=True)
    for name in ['treatment','allowed']:
        c=create_case(name)
        q,sub=destination(c,'live',False)
        c['message']='original encrypted archive '+name+' '+PREFIX
        c['publication']=call(name+'-publish-original','sns','publish',{'TopicArn':c['topic'],'Message':c['message'],'MessageGroupId':'group','MessageDeduplicationId':uuid.uuid4().hex})
        save()
        c['live_receipt']=receive(c,'live',q,sub)
        c['initial_replay_receipt']=replay(c,'initial-replay')
        if not c['initial_replay_receipt']:
            raise RuntimeError('No positive baseline replay for '+name)
    treatment,allowed=CASES
    call('treatment-add-only-service-deny','kms','put-key-policy',{'KeyId':treatment['key'],'PolicyName':'default','Policy':policy(True)})
    controls(treatment,'after-deny')
    encrypted=call('treatment-owner-encrypt-control','kms','encrypt',{'KeyId':treatment['key'],'Plaintext':'b3duZWQgcG9saWN5IGNvbnRyb2w=','EncryptionContext':{'stackd-probe':PREFIX}})
    call('treatment-owner-decrypt-control','kms','decrypt',{'KeyId':treatment['key'],'CiphertextBlob':encrypted['CiphertextBlob'],'EncryptionContext':{'stackd-probe':PREFIX}})
    print('ArchiveDeny baseline and enabled-owner controls complete; idle until twenty minutes',flush=True)
    until(1200,'twenty-minute-idle')
    for c in CASES:
        controls(c,'before-separated-replay')
    tq,ts=destination(treatment,'separated-deny',True)
    aq,ass=destination(allowed,'same-age-allowed',True)
    allowed['same_age_allowed_receipt']=receive(allowed,'same-age-allowed',aq,ass)
    treatment['separated_deny_receipt']=receive(treatment,'separated-deny',tq,ts)
    controls(treatment,'after-separated-replay')
    if treatment['separated_deny_receipt']:
        until(1560,'twenty-six-minute-idle-after-denied-success')
        controls(treatment,'before-second-separated-replay')
        treatment['second_separated_deny_receipt']=replay(treatment,'second-separated-deny')
        controls(treatment,'after-second-separated-replay')
    call('treatment-remove-only-service-deny','kms','put-key-policy',{'KeyId':treatment['key'],'PolicyName':'default','Policy':policy(False)})
    controls(treatment,'restored')
    treatment['restored_original_receipt']=replay(treatment,'restored-original')
    if not treatment['restored_original_receipt']:
        time.sleep(30)
        treatment['restored_original_retry_receipt']=replay(treatment,'restored-original-retry')
    for c in CASES:
        controls(c,'final-enabled')
    print('ArchiveDeny replay phases complete; awaiting CloudTrail propagation',flush=True)
    until(1800,'thirty-minute-cloudtrail-propagation')
    trail('thirty-minute-decrypt-cloudtrail')
    until(1980,'thirty-three-minute-cloudtrail-propagation')
    trail('final-decrypt-cloudtrail')
    call('treatment-denied-request-final-status','sns','get-subscription-attributes',{'SubscriptionArn':ts})
except Exception as exc:
    DATA['capture_error']=str(exc)
    DATA['capture_traceback']=traceback.format_exc()
    print(DATA['capture_traceback'],flush=True)
finally:
    DATA['owned_resources']={'topics':[c.get('topic') for c in CASES], 'keys':[c.get('key') for c in CASES], 'queues':QUEUES,'subscriptions':SUBS,'functions':[],'roles':[],'log_groups':[]}
    save()
    for sub in reversed(SUBS):
        cleanup_call('unsubscribe','sns','unsubscribe',{'SubscriptionArn':sub})
        cleanup_call('subscription-absence','sns','get-subscription-attributes',{'SubscriptionArn':sub})
    for c in CASES:
        if 'topic' in c:
            cleanup_call(c['name']+'-disable-archive','sns','set-topic-attributes',{'TopicArn':c['topic'],'AttributeName':'ArchivePolicy','AttributeValue':'{}'})
            cleanup_call(c['name']+'-verify-disabled-archive','sns','get-topic-attributes',{'TopicArn':c['topic']})
            cleanup_call(c['name']+'-delete-topic','sns','delete-topic',{'TopicArn':c['topic']})
            cleanup_call(c['name']+'-topic-absence','sns','get-topic-attributes',{'TopicArn':c['topic']})
    for q in reversed(QUEUES):
        cleanup_call('delete-queue','sqs','delete-queue',{'QueueUrl':q})
    for c in CASES:
        if 'key' in c:
            cleanup_call(c['name']+'-schedule-key-deletion','kms','schedule-key-deletion',{'KeyId':c['key'],'PendingWindowInDays':7})
            c['residual_key']=cleanup_call(c['name']+'-verify-key-pending-deletion','kms','describe-key',{'KeyId':c['key']}).get('KeyMetadata')
    time.sleep(65)
    for q in QUEUES:
        cleanup_call('independent-queue-absence','sqs','get-queue-attributes',{'QueueUrl':q,'AttributeNames':['QueueArn']})
    cleanup_call('independent-prefix-queue-list','sqs','list-queues',{'QueueNamePrefix':PREFIX},paginate=True)
    for sub in SUBS:
        cleanup_call('independent-subscription-absence','sns','get-subscription-attributes',{'SubscriptionArn':sub})
    for c in CASES:
        if 'topic' in c:
            cleanup_call(c['name']+'-independent-topic-absence','sns','get-topic-attributes',{'TopicArn':c['topic']})
    DATA['capture_program']=Path(__file__).read_text()
    DATA['finished']=stamp()
    save()
    print(json.dumps({'fixture':str(OUTPUT),'receipts':len(DATA['receipts']),'error':DATA.get('capture_error'),'keys':[c.get('key') for c in CASES]}),flush=True)
